// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialMinSum, uint256 newMinSum, address caller, uint256 lockTime, uint256 amount) public {
        // Bound inputs to avoid overflows and unreasonable values
        initialMinSum = bound(initialMinSum, 0, 1e18);
        newMinSum = bound(newMinSum, 0, 1e18);
        lockTime = bound(lockTime, 0, 1e6);
        amount = bound(amount, 0, 1e18);
        vm.assume(caller != address(0));

        // Set initial MinSum and LogFile, then initialize
        c.SetMinSum(initialMinSum);
        c.SetLogFile(makeAddr("log"));
        c.Initialized();

        // Record MinSum after initialization
        uint256 minSumBefore = c.MinSum();

        // Try to mutate MinSum via SetMinSum (should revert after initialization in reference)
        // Then call Collect
        vm.prank(caller);
        // First try calling SetMinSum to change MinSum — in reference it reverts, in buggy it succeeds
        (bool successSet, ) = address(c).call(abi.encodeWithSelector(c.SetMinSum.selector, newMinSum));
        // Then call Collect — ensure we don't revert due to insufficient balance (fund the caller)
        vm.deal(caller, amount);
        vm.prank(caller);
        (bool successCollect, ) = address(c).call{value: amount}(abi.encodeWithSelector(c.Collect.selector, amount));
        // Regardless of revert, the rule: MinSum after should equal minSumBefore (the value after init)
        // Because reference never allows SetMinSum after init, so MinSum unchanged.
        // In buggy version, if SetMinSum succeeded, MinSum may change; if it reverted, same.
        // But if SetMinSum reverted (successSet false), then MinSum unchanged; if succeeded, changed.
        // We assert that MinSum is unchanged from after-initialization value.
        uint256 minSumAfter = c.MinSum();
        assertTrue(minSumAfter == minSumBefore, "MinSum changed after initialization");
    }
}

